  exists (fx' : FPState) E' R' Mc',
    env_agree (s_next ss) E E' /\ (s_next ss <= s_next ss')%nat /\ INV2 E' ss' R' Mc'
    /\ msteps segs (@mkst fx R (Z_to_bv 64 (s_pc ss)) Mc (seg_rom segs))
                   (@mkst fx' R' (Z_to_bv 64 (s_pc ss')) Mc' (seg_rom segs)).
Proof.
