Lemma eval_all_in_sound : forall fuel E J e v0 lo hi v,
  eval_all_in fuel J e v0 lo hi = true -> v0 <= v < v0 + Z.of_nat fuel ->
  lo <= bv_unsigned (edenot (APS.upd E J (Z_to_bv 64 v)) e) <= hi.
