Lemma find_blob_cover_sound : forall fk k rb rk kb kk id,
  find_blob_cover fk k rb rk = Some (kb, kk, id) ->
  exists len, In (KBlob (SA kb kk) len id) k /\ xinside fk rb rk (ELit 1) kb kk len = true.
Proof.
