Lemma piece_defined : forall E M K b o n,
  kentry_ok segs E M K -> piece_of K = Some (b, o, n) ->
  forall x : Z, estart E (SA b o) <= x < estart E (SA b o) + elenZ E n -> APS.in_hull A x = false ->
    0 <= x < 2 ^ 64 /\ M (Z_to_bv 64 x) <> None.
Proof.
