  know_ok segs E M kn -> chain_cover fuel kn tb pos goal = true ->
  (forall x : Z, lo <= x < xt_den E pos -> APS.in_hull A x = false -> 0 <= x < 2 ^ 64 /\ M (Z_to_bv 64 x) <> None) ->
