Definition cell_env (kn : list kentry) (Eb : env) (E1 : env) (cs : list (saddr * nat * nat)) : env :=
  fold_right (fun x E2 => match x with (a, w, c) =>
                match cell_value kn a w with Some e => APS.upd E2 c (edenot Eb e) | None => E2 end end) E1 cs.

