Lemma find_bne_sound : forall fk brs id rb rk kb kk v,
  find_bne fk brs id rb rk kb kk v = true ->
  exists j, In (BNe id j v) brs
    /\ lin_ge0 fk [(rb, rk)] [(kb, kk); (j, 0)] = true /\ lin_ge0 fk [(kb, kk); (j, 0)] [(rb, rk)] = true.
Proof.
