(* [comment removed for export] *)
Lemma body_state_INV2 : forall E inv R Mc J N nhi (j Nv : Z),
  INV2 E inv R Mc -> ev E J = Z_to_bv 64 j -> bv_unsigned (edenot E N) = Nv ->
  0 <= j < Nv -> Nv <= nhi -> nhi < two64 ->
  INV2 E (body_state J N nhi inv) R Mc.
Proof.
