  forallb (fun seg => (lo <=? Z.of_N (seg_base seg)) && (Z.of_N (seg_base seg) + Z.of_N (seg_size seg) <=? hi))%bool sgs = true ->
  (x < lo \/ hi <= x) -> find_segment sgs x 1 = None.
